const navigation:[View,string,string,any][]=[["dashboard","Panel","Overview",LayoutDashboard],["contacts","Clientes","Clients",Users],["estimates","Cotizaciones","Estimates",FileText],["projects","Obras","Projects",HardHat],["cash","Caja","Cash flow",Wallet],["tasks","Tareas","Tasks",ListChecks],["connections","Conexiones","Connections",Plug],["system","Cómo operamos","How we operate",BookOpen]];
