 const load=useCallback(async(mode:boolean)=>{setLoading(true);try{const response=await fetch(`/api/ops?demo=${mode?1:0}`,{cache:"no-store"});const d:any=await response.json();if(!response.ok)throw new Error(d.error);setRecords(d.records);setAudit(d.audit);setConnections(d.connections);setInfra(d.infrastructure||{});setError("");return d;}catch(e:any){setError(e.message||"No se pudo cargar. Intenta nuevamente.");throw e;}finally{setLoading(false);}},[]);
 useEffect(()=>{load(demo).catch(()=>{});},[demo,load]);
 useEffect(()=>{const v=location.hash.slice(1);if(navigation.some(n=>n[0]===v))setView(v as View);},[]);
