 useEffect(()=>{const context=(document as any).modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const tools=[{name:"read_build_dreams_state",description:"Read the visible company or example records and current operational totals.",title:"Read company status",inputSchema:{type:"object",properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async()=>({demo,records,metrics})},{name:"start_build_dreams_contact",description:"Open the new contact form for review. Does not create a contact.",title:"Start new contact",inputSchema:{type:"object",properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:async(input:any)=>{if(input&&Object.keys(input).length)throw new Error("No fields expected.");open("contact");return{form:"contact",saved:false};}}];for(const tool of tools)try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}return()=>lifecycle.abort();},[records,demo,metrics]);
