 {modal==="estimate"&&<>{choiceField("contactId",t("Cliente","Client"),contacts.map(c=>[c.id,c.data.name]))}{field("title",t("Nombre del proyecto","Project name"))}{longField("scope",t("Alcance incluido","Included scope"),true)}{longField("exclusions",t("Exclusiones y condiciones","Exclusions and conditions"))}<div className="wide line-items"><Table><TableHeader><TableRow><TableHead>{t("Partida de costo","Cost item")}</TableHead><TableHead>{t("Cant.","Qty.")}</TableHead><TableHead>{t("Unidad","Unit")}</TableHead><TableHead>{t("Costo / unidad","Cost / unit")}</TableHead><TableHead/></TableRow></TableHeader><TableBody>{f.items?.map((item:any,i:number)=><TableRow key={i}><TableCell><Input required value={item.description} aria-label={`${t("Descripción partida","Item description")} ${i+1}`} onChange={e=>set("items",f.items.map((x:any,j:number)=>i===j?{...x,description:e.target.value}:x))}/></TableCell><TableCell><Input required type="number" min="0.001" step="any" value={item.quantity} aria-label={`${t("Cantidad","Quantity")} ${i+1}`} onChange={e=>set("items",f.items.map((x:any,j:number)=>i===j?{...x,quantity:Number(e.target.value)}:x))}/></TableCell><TableCell><Input value={item.unit} aria-label={`${t("Unidad","Unit")} ${i+1}`} onChange={e=>set("items",f.items.map((x:any,j:number)=>i===j?{...x,unit:e.target.value}:x))}/></TableCell><TableCell><Input required type="number" min="0" step="0.01" value={item.unitCostCents/100} aria-label={`${t("Costo unitario USD","Unit cost USD")} ${i+1}`} onChange={e=>set("items",f.items.map((x:any,j:number)=>i===j?{...x,unitCostCents:Math.round(Number(e.target.value)*100)}:x))}/></TableCell><TableCell><Button type="button" size="icon" variant="ghost" disabled={f.items.length===1} aria-label={t("Quitar partida","Remove item")} onClick={()=>set("items",f.items.filter((_:any,j:number)=>j!==i))}><X size={15}/></Button></TableCell></TableRow>)}</TableBody></Table><Button type="button" variant="outline" onClick={()=>set("items",[...f.items,{description:"",quantity:1,unit:"lote",unitCostCents:0}])}><Plus size={16}/>{t("Agregar costo","Add cost")}</Button></div>{field("overheadPct",t("Gastos generales %","Overhead %"),"number")}{field("contingencyPct",t("Contingencia %","Contingency %"),"number")}{field("marginPct",t("Margen objetivo sobre venta %","Target margin on revenue %"),"number")}{field("depositPct",t("Anticipo acordado %","Agreed deposit %"),"number")}{field("validUntil",t("Válida hasta","Valid until"),"date")}{field("owner",t("Responsable","Owner"))}{estimatePreview&&<div className="wide quote-calculation"><span>{t("Costo completo","Full cost")}<strong>{money(estimatePreview.costCents)}</strong></span><span>{t("Utilidad estimada","Estimated profit")}<strong>{money(estimatePreview.profitCents)}</strong></span><span>{t("Precio antes de impuestos","Price before taxes")}<strong>{money(estimatePreview.priceCents)}</strong></span></div>}</>}
