 {modal==="ledger"&&<>{choiceField("projectId",t("Obra","Project"),projects.map(p=>[p.id,p.data.title]))}{choiceField("type",t("Tipo de movimiento","Entry type"),[["expense",t("Costo","Cost")],["payment",t("Cobro recibido","Receipt collected")]])}{field("description",t("Concepto","Description"))}{cashField("amountCents",t("Monto","Amount"))}{field("date",t("Fecha de pago / compromiso","Payment / commitment date"),"date")}{field("reference",t("Factura / recibo / Jobber ID","Invoice / receipt / Jobber ID"))}{f.type==="expense"&&<label className="check-label wide"><Checkbox checked={f.paid} onCheckedChange={v=>set("paid",v===true)}/>{t("El costo ya fue pagado.","The cost has been paid.")}</label>}</>}
