 {modal==="change"&&<>{choiceField("projectId",t("Obra","Project"),projects.map(p=>[p.id,p.data.title]))}{field("title",t("Nombre del cambio","Change title"))}{longField("scope",t("Alcance aprobado","Approved scope"),true)}{cashField("priceCents",t("Precio adicional al cliente","Additional client price"))}{cashField("costCents",t("Costo adicional estimado","Estimated additional cost"))}{field("acceptedBy",t("Quién aceptó","Accepted by"))}{field("signedRef",t("Referencia del cambio escrito","Written change reference"))}</>}
