function Metric({label,value,sub,icon:Icon}:{label:string;value:string;sub:string;icon:any}){return <article className="metric"><div><span>{label}</span><Icon size={19}/></div><strong>{value}</strong><p>{sub}</p></article>;}
function TaskRow({record:r,lang,onToggle}:{record:Entity;lang:number;onToggle:()=>void}){return <div className={`task-row ${r.data.done?"task-done":""}`}><Checkbox aria-label={`${lang?"Complete":"Completar"}: ${r.data.title}`} checked={r.data.done} onCheckedChange={onToggle}/><div><strong>{r.data.title}</strong><span>{r.data.owner}{r.data.notes&&` · ${r.data.notes}`}</span></div><span className={r.data.due<todayChicago()&&!r.data.done?"overdue":"task-date"}>{dateLabel(r.data.due)}</span></div>;}
function ClientQuote({record:r,contact,lang}:{record:Entity;contact?:Entity;lang:number}){if(!r)return null;const e=r.data,t=(es:string,en:string)=>lang?en:es;return <><article className="client-quote" id="print-quote"><div className="quote-brand"><Building2/><strong>BUILD DREAMS MM</strong><span>DFW</span></div><div className="quote-header"><h2>{t("Cotización","Estimate")}</h2><p>BD-{r.id.slice(0,6).toUpperCase()} · {t("Válida hasta","Valid until")} {e.validUntil}</p></div><h3>{e.title}</h3><p><strong>{t("Cliente","Client")}:</strong> {contact?.data.name} {contact?.data.company&&`· ${contact.data.company}`}</p><h4>{t("Alcance incluido","Included scope")}</h4><p className="preserve-lines">{e.scope}</p><h4>{t("Exclusiones y condiciones","Exclusions and conditions")}</h4><p className="preserve-lines">{e.exclusions||t("Confirmar por escrito antes de contratar.","Confirm in writing before contracting.")}</p><div className="client-quote-total"><span>{t("Precio antes de impuestos","Price before taxes")}</span><strong>{money(e.priceCents)}</strong></div><p>{t("Anticipo acordado","Agreed deposit")}: {e.depositPct}% · {money(Math.round(e.priceCents*e.depositPct/100))}</p><p className="quote-note">{t("Confirmar medidas, diseño, permisos aplicables y tratamiento fiscal antes del acuerdo final. Todo cambio requiere aceptación escrita con su impacto en precio y calendario.","Confirm dimensions, design, applicable permits and tax treatment before final agreement. Changes require written acceptance with price and schedule impact.")}</p>{e.acceptedBy&&<p>{t("Aceptación registrada","Recorded acceptance")}: {e.acceptedBy} · {e.signedRef}</p>}</article><Button className="no-print" onClick={()=>window.print()}><Printer size={16}/>{t("Imprimir / guardar PDF","Print / save PDF")}</Button></>;}
